ground_truth_sql:
SELECT "nct", "author", "year", "publication_type", "trial_phase", "control_type", "cancer_type", "ici_name", "treatment_regimen"
FROM public."clinical_trials"
WHERE "cancer_type" = 'Colorectal' AND "trial_phase" = 'Phase 3' AND "control_type" = 'Chemo';

gt_sql_final:
SELECT "nct", "author", "year", "originial_publication_or_follow_up", "trial_phase", "type_of_control", "cancer_type", "name_of_ici", "treatment_regimen"
FROM public."clinical_trials"
WHERE "cancer_type" = 'Colorectal' AND "trial_phase" = 'Phase 3' AND "type_of_control" = 'Chemo';
